#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;

int sum_mod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int product_mod(int a, int b) {
    long long res = 1LL * a * b;
    if (res >= MOD) res %= MOD;
    return (int)res;
}

namespace matrix {
    template<int N, int M>
    class Mat {
    public:
        int mat[N][M];

        void clear() {
            memset(mat, 0, sizeof(mat));
        }

        void set_identity() {
            clear();
            for (int i = 0; i < min(N, M); ++i)
                mat[i][i] = 1;
        }

        Mat<M, N> transpose() const {
            Mat<M, N> t;
            t.clear();
            for (int i = 0; i < M; ++i)
                for (int j = 0; j < N; ++j)
                    t[i][j] = mat[j][i];
            return t;
        }

        const int* row(int r) const {
            return mat[r];
        }

        int* row(int r) {
            return mat[r];
        }

        Mat<N, M> add(const Mat<N, M>& other) const {
            Mat<N, M> res;
            for (int i = 0; i < N; ++i)
                for (int j = 0; j < M; ++j)
                    res[i][j] = sum_mod(mat[i][j], other[i][j]);
            return res;
        }

        Mat<N, M> scale(int scalar) const {
            Mat<N, M> res = *this;
            for (int i = 0; i < N; ++i)
                for (int j = 0; j < M; ++j)
                    res[i][j] = product_mod(res[i][j], scalar);
            return res;
        }

        template<int X>
        friend Mat<N, M> multiply(const Mat<N, X>& a, const Mat<X, M>& b) {
            Mat<N, M> out;
            out.clear();
            for (int i = 0; i < N; ++i) {
                for (int j = 0; j < X; ++j) {
                    if (a[i][j]) {
                        for (int k = 0; k < M; ++k) {
                            out[i][k] = sum_mod(out[i][k], product_mod(a[i][j], b[j][k]));
                        }
                    }
                }
            }
            return out;
        }
    };
}

using namespace matrix;
typedef long long ll;

ll n;
int K;
vector<int> digits;
Mat<35, 35> A[65][35], S[65][35], P[65][35], result;

int main() {
    scanf("%lld%d", &n, &K);
    for (int i = 0; i < K; ++i) {
        A[0][i].set_identity();
        for (int j = 0; j <= K; ++j)
            A[0][i][i][j] = 1;
    }
    ll length = K;
    for (int i = 1; length <= n; ++i, length *= K) {
        S[i - 1][K - 1] = A[i - 1][K - 1];
        for (int j = K - 2; j >= 0; --j)
            S[i - 1][j] = A[i - 1][j] * S[i - 1][j + 1];
        P[i - 1][0] = A[i - 1][0];
        for (int j = 1; j < K; ++j)
            P[i - 1][j] = P[i - 1][j - 1] * A[i - 1][j];
        A[i][0] = S[i - 1][0];
        for (int j = 1; j < K; ++j)
            A[i][j] = S[i - 1][j] * P[i - 1][j - 1];
    }
    while (n) {
        digits.push_back(n % K);
        n /= K;
    }
    int s = 0;
    result.set_identity();
    for (int i = (int)digits.size() - 1; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j)
            result = result * A[i][(j + s) % K];
        s = (s + digits[i]) % K;
    }
    int res = 1;
    for (int i = 0; i < K; ++i)
        res = sum_mod(res, result[i][K]);
    printf("%d\n", res);
    return 0;
}
